entries[237746] = { ["name"] = "Warswords of the Valarjar", ["text"] = "Legion Remix\nBinds when picked up\nUnique\nTwo-Hand Sword\n5 - 9 Damage Speed 3.60\n(1.9 damage per second)\n+3 Strength\n+4 Stamina\nClasses: Warrior\nRequires level 10 to 90 ( 90)\nRequires Fury Warrior\n\"Helya's betrayal shall never be forgiven. Let her rot beneath the waves, far from the Halls of Valor.\"" }
entries[237747] = { ["name"] = "Warswords of the Valarjar", ["text"] = "Binds when picked up\nUnique\nTwo-Hand Sword\n5 - 9 Damage Speed 3.60\n(1.9 damage per second)\n+3 Strength\n+4 Stamina\nClasses: Warrior\nRequires level 10 to 90 ( 90)\nRequires Fury Warrior\n\"In truth, it is her power that makes these weapons truly magnificent. Her power, laced with her hatred, crashes endlessly against Odyn's spirit. The tension between those energies will forever permeate these blades...\"" }
