entries[238386] = { ["name"] = "Void-Touched Fragment", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\n+18 [Agility or Strength or Intellect]\nEquip: Your harmful spells and abilities have a chance to grant you a Void Fragment. Slaying an enemy guarantees a Void Fragment. Upon collecting 15 Fragments, you absorb their void energy, increasing your Mastery by 207 for 10 sec.\nSell Price:" }
