entries[238678] = { ["name"] = "Lesser Rune of Echoing Void", ["text"] = "Binds to Warband\nUse: Apply Lesser Rune of the Echoing Void to a helm.\n\nYour damaging abilities build the Echoing Void. Each time it builds, Echoing Void has a chance to collapse, dealing ( 1 * 708) Shadow damage to all nearby enemies every 1 sec until no stacks remain.\n\nCannot be applied to items lower than level 350. This effect is fleeting and will only work during The War Within Season 2.\nSell Price:" }
entries[238680] = { ["name"] = "Greater Rune of Echoing Void", ["text"] = "Binds to Warband\nUse: Apply Greater Rune of the Echoing Void to a helm.\n\nYour damaging abilities build the Echoing Void. Each time it builds, Echoing Void has a chance to collapse, dealing ( 1 * 1215) Shadow damage to all nearby enemies every 1 sec until no stacks remain.\n\nCannot be applied to items lower than level 350. This effect is fleeting and will only work during The War Within Season 2.\nSell Price:" }
