entries[238829] = { ["name"] = "Radiant Imperial Lynx", ["text"] = "Binds when picked up\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount. This mount changes depending on your Riding skill and location.\nSummons and dismisses this mount.\nRequires level 1 to 90 ( 90)\nRequires Apprentice Riding\nRequires Renown Rank 9 with Flame's Radiance.\n\n\"The Radiant Imperial Lynx embodies the ongoing strength and courage it takes to chase back the darkness. They hoist us up so that we may hold our torches high for all who seek refuge from the encroaching darkness.\"\nVendor:\nLars Bronsmaelt\nZone:\nHallowfall" }
