entries[238897] = { ["name"] = "Spring Harvesthog", ["text"] = "Binds when picked up\nUnique\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount.\nSummons and dismisses this mount.\nRequires level 1 to 90 ( 90)\nRequires Apprentice Riding\nSell Price:\n\"The Spring Harvesthog is at its most energetic in the early morning. It will spend most of its day snuffling for food or bellowing out calls for other harvesthogs.\"\nTrading Post" }
entries[238900] = { ["name"] = "Summer Harvesthog", ["text"] = "Binds when picked up\nUnique\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount.\nSummons and dismisses this mount.\nRequires level 1 to 90 ( 90)\nRequires Apprentice Riding\nSell Price:\n\"The Summer Harvesthog enjoys laying out in the sun or going for a swim in a clear lake. They are excellent at foraging for food, but need to be coaxed into it.\"\nTrading Post" }
entries[238901] = { ["name"] = "Winter Harvesthog", ["text"] = "Binds when picked up\nUnique\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount.\nSummons and dismisses this mount.\nRequires level 1 to 90 ( 90)\nRequires Apprentice Riding\nSell Price:\n\"Winter Harvesthogs are primarily nocturnal creatures. They are slightly slower than other harvesthogs, but their endurance is unmatched.\"\nTrading Post" }
entries[238902] = { ["name"] = "Autumn Harvesthog", ["text"] = "Binds when picked up\nUnique\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount.\nSummons and dismisses this mount.\nRequires level 1 to 90 ( 90)\nRequires Apprentice Riding\nSell Price:\n\"Autumn Harvesthogs excel in snuffling for food in the cooler months. Their keen sense of smell makes them excellent companions for a forrest forage, but difficult to control in aromatic settings.\"\nTrading Post" }
entries[238903] = { ["name"] = "Appropriated Azerothian Camera", ["text"] = "Quest Item\nUse: Stand still to document nearby flora and fauna. (3 Sec Cooldown)\n\"Has the initials \"W.F.\" on the back. How Ve'nari got this is a mystery.\"" }
entries[238904] = { ["name"] = "Anima Vacuum", ["text"] = "Quest Item\nUse: Suck up nearby critters, ne'er-do-wells, and cosmic entities (probably).\n\nMay walk while casting. (3 Sec Cooldown)\n\"Apparently there is a portal in the back that leads directly to K'aresh. You've been assured it's safe. Probably.\"" }
