entries[238912] = { ["name"] = "Tranquilizing Dart", ["text"] = "Quest Item\nUse: Shoots a Tranquilizer Dart at your target, causing them to fall into a deep and blissful slumber.\n\"Tranquilizes anything it's thrown at by temporarily disrupting their spiritual web. Non-invasive and pain-free. Apparently a common prank to pull on unsuspecting friends.\"" }
