entries[238941] = { ["name"] = "Coldflame Cormaera", ["text"] = "Binds when picked up\nUnique\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount.\nSummons and dismisses a Coldflame Cormaera. This mount changes depending on your Riding skill and location.\nRequires level 1 to 90 ( 90)\nRequires Apprentice Riding\nSell Price:\n\"During the war of the elemental lords, Cormaera were often used as beasts of burden for the Firelord's most loyal lieutenants.\"\nTrading Post" }
entries[238942] = { ["name"] = "Weechi", ["text"] = "Binds to Warband\nUse: Teaches you how to summon this customizable companion. You can customize this companion at a Pet Grooming Station.\nRight Click to summon and dismiss this customizable companion.\nRequires level 1 to 90 ( 90)" }
entries[238943] = { ["name"] = "Prophet's Great Raven", ["text"] = "Binds when picked up\nUnique\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount.\nSummons and dismisses the Prophet's Great Raven.\nRequires level 1 to 90 ( 90)\nRequires Apprentice Riding\nSell Price:\n\"As the Prophet, Medivh delivered his missives in the form of a black raven. Although not as impressive as shapeshifting, this bird still carries all the prestige of its namesake.\"\nIn-Game Shop" }
