entries[238966] = { ["name"] = "Felborn Cormaera", ["text"] = "Binds when picked up\nUnique\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount.\nSummons and dismisses a Felborn Cormaera. This mount changes depending on your Riding skill and location.\nRequires level 1 to 90 ( 90)\nRequires Apprentice Riding\nSell Price:\n\"Cormaera were an early species on Azeroth that were claimed by elemental lords.\"\nPromotion" }
