entries[239074] = { ["name"] = "Void Lure", ["text"] = "Quest Item\nUnique\nUse: Throw the void lure on the remains of a defeated Void Tempest at the Fracture of Laacuna to attract Ramon'ta. (6 Sec Cooldown)\n\"These orbs can contain and release void energy, acting as both lure and repository depending on the need.\"" }
entries[239075] = { ["name"] = "Wrought Iron Chandelier", ["text"] = "1\nHousing Decor\nBinds to Warband\nUse: This Decor will be added immediately on purchase to your House Chest.\nSell Price:" }
entries[239076] = { ["name"] = "Herald of Sa'bak", ["text"] = "Binds when picked up\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount.\nSummons and dismisses this mount.\nRequires level 1 to 90 ( 90)\nRequires Apprentice Riding\n\n\"The Tol'vir tell of the legendary Sa'bak, a great crocolisk believed to have emerged from the sacred valley of Un'Goro crater. Although few have ever seen Sa'bak in the flesh, many believe he was blessed by the Titan Keepers to safeguard the vast waterways of Uldum.\"\nIn-Game Shop" }
entries[239077] = { ["name"] = "Mound of Mildly-Meaningful Meat", ["text"] = "Binds when picked up\n\"A pile of meat left over from a creature you skinned. It could be from the creature itself, or something it ate. Only one way to find out!\"\n<Right Click to Open>" }
entries[239078] = { ["name"] = "Lesser Rune of Infinite Stars", ["text"] = "Binds to Warband\nUse: Apply Lesser Rune of Infinite Stars to a helm.\n\nYour spells and abilities have a chance to strike a nearby enemy with an Infinite Star, dealing ( 1 * 2084) Arcane damage and increasing their damage taken from your Infinite Stars by ( 1 * 729), stacking up to 6 times before resetting.\n\nCannot be applied to items lower than level 350. This effect is fleeting and will only work during The War Within Season 2.\nSell Price:" }
entries[239080] = { ["name"] = "Greater Rune of Infinite Stars", ["text"] = "Binds to Warband\nUse: Apply Greater Rune of Infinite Stars to a helm.\n\nYour spells and abilities have a chance to strike a nearby enemy with an Infinite Star, dealing ( 1 * 3572) Arcane damage and increasing their damage taken from your Infinite Stars by ( 1 * 1250), stacking up to 6 times before resetting.\n\nCannot be applied to items lower than level 350. This effect is fleeting and will only work during The War Within Season 2.\nSell Price:" }
entries[239082] = { ["name"] = "Sa'bak's Blessed", ["text"] = "Binds to Warband\nUse: Teaches you how to summon this companion.\nRight Click to summon and dismiss this companion.\nRequires level 1 to 90 ( 90)" }
entries[239083] = { ["name"] = "Head of Brulagh the Crusher", ["text"] = "Quest Item\nRequires level 83 to 88 ( 88)\n\"Flecked with gore and battered with bruises.\"" }
entries[239084] = { ["name"] = "Lesser Rune of Gushing Wound", ["text"] = "Binds to Warband\nUse: Apply Lesser Rune of Gushing Wound to a helm.\n\nYour damaging spells and abilities have a chance to cause your target to ooze blood for ( 1 * 373 * 7) damage over 7 sec.\n\nCannot be applied to items lower than level 350. This effect is fleeting and will only work during The War Within Season 2.\nSell Price:" }
entries[239086] = { ["name"] = "Greater Rune of Gushing Wound", ["text"] = "Binds to Warband\nUse: Apply Greater Rune of Gushing Wound to a helm.\n\nYour damaging spells and abilities have a chance to cause your target to ooze blood for ( 1 * 639 * 7) damage over 7 sec.\n\nCannot be applied to items lower than level 350. This effect is fleeting and will only work during The War Within Season 2.\nSell Price:" }
entries[239088] = { ["name"] = "Lesser Rune of the Twisted Appendage", ["text"] = "Binds to Warband\nUse: Apply Lesser Rune of the Twisted Appendage to a helm.\n\nYour attacks have a chance to spawn a tentacle which Mind Flays your target for ( 1 * 938) Shadow damage every second for 10 sec.\n\nCannot be applied to items lower than level 350. This effect is fleeting and will only work during The War Within Season 2.\nSell Price:" }
entries[239090] = { ["name"] = "Greater Rune of the Twisted Appendage", ["text"] = "Binds to Warband\nUse: Apply Greater Rune of the Twisted Appendage to a helm.\n\nYour attacks have a chance to spawn a tentacle which Mind Flays your target for ( 1 * 1607) Shadow damage every second for 10 sec.\n\nCannot be applied to items lower than level 350. This effect is fleeting and will only work during The War Within Season 2.\nSell Price:" }
entries[239093] = { ["name"] = "Lesser Rune of the Void Ritual", ["text"] = "Binds to Warband\nUse: Apply Lesser Rune of the Void Ritual to a helm.\n\nGain Void Ritual, giving your spells and abilities a chance to increase all secondary stats by 0 every sec for 20 sec.\n\nCannot be applied to items lower than level 350. This effect is fleeting and will only work during The War Within Season 2.\nSell Price:" }
entries[239095] = { ["name"] = "Greater Rune of the Void Ritual", ["text"] = "Binds to Warband\nUse: Apply Greater Rune of the Void Ritual to a helm.\n\nGain Void Ritual, giving your spells and abilities a chance to increase all secondary stats by 1 every sec for 20 sec.\n\nCannot be applied to items lower than level 350. This effect is fleeting and will only work during The War Within Season 2.\nSell Price:" }
entries[239098] = { ["name"] = "Neighborhood Charter", ["text"] = "Quest Item\nUnique\nUse: Opens neighborhood charter. Allows you to request signatures from other players. (10 Sec Cooldown)\n\"A charter to create your own neighborhood.\"" }
entries[239101] = { ["name"] = "Voidcrawler", ["text"] = "Binds when picked up\nUse: Teaches you how to summon and dismiss this companion.\nRight Click to summon and dismiss this companion.\nRequires level 1 to 90 ( 90)\nSell Price:" }
entries[239105] = { ["name"] = "Unusual Gems", ["text"] = "Binds to Warband\nUnique\nCrafting Reagent\n\"A pair of gems with facets cut to resemble snake eyes. Found in Horrific Visions.\"" }
